import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v1.21 released — Auth 深化 (WebAuthn + Passkey + OAuth 2.1 + OIDC の 4 protocol 統一 mock)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.21/gh-discussions-announcement.md","filePath":"announcements/v1.21/gh-discussions-announcement.md"}'),r={name:"announcements/v1.21/gh-discussions-announcement.md"};function n(s,e,c,d,h,l){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="kiwa-v1-21-released-—-auth-深化-webauthn-passkey-oauth-2-1-oidc-の-4-protocol-統一-mock" tabindex="-1">kiwa v1.21 released — Auth 深化 (WebAuthn + Passkey + OAuth 2.1 + OIDC の 4 protocol 統一 mock) <a class="header-anchor" href="#kiwa-v1-21-released-—-auth-深化-webauthn-passkey-oauth-2-1-oidc-の-4-protocol-統一-mock" aria-label="Permalink to &quot;kiwa v1.21 released — Auth 深化 (WebAuthn + Passkey + OAuth 2.1 + OIDC の 4 protocol 統一 mock)&quot;">​</a></h1><p>v1.21 is out. After v1.20&#39;s Streaming 深化 milestone (event-driven backbone testing — Kafka + Redpanda + NATS in one unified mock), v1.21 turns to <strong>the 2026 web-auth main stage</strong> — WebAuthn Level 3 (Virtual Authenticator API + credential creation + assertion), Passkey (platform + roaming authenticator + sync fabric), OAuth 2.1 (RFC 9700 + PKCE mandatory + DPoP sender-constrained token), and OIDC (id_token verify + Discovery + Dynamic Client Registration + Federation) — four new protocol adapters bolted onto <code>@kiwa-lab/auth</code>, plus three dogfood apps that stress every testing-hard-part production teams complain about (virtual authenticator / PKCE + DPoP / id_token verify / discovery + federation).</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-lab/auth</code> v0.4.0</strong> (new 4 protocol adapters). Auth-protocol testing mock covering the 4 web auth protocols production teams hit in 2026 — WebAuthn L3, Passkey, OAuth 2.1, OIDC — in one API surface, sitting alongside the existing 6 provider adapters (NextAuth v5 + Lucia v3 + Better Auth + Clerk + Auth0 + Supabase Auth). <code>createWebAuthnEnv()</code> returns a Chrome Virtual Authenticator-shaped credential store + navigator.credentials mock covering <code>create()</code> (attestation format <code>none</code> / <code>packed</code> / <code>fido-u2f</code>, authenticator selection criteria <code>userVerification</code> / <code>residentKey</code> / <code>authenticatorAttachment</code>) + <code>get()</code> (assertion + sign counter monotonicity + user verification flag). <code>createPasskeyEnv()</code> layers platform authenticator vs roaming authenticator boundaries + <code>credProps.rk</code> boolean + sync fabric mock (iCloud Keychain / Google Password Manager) with credential ID + sync state transitions. <code>createOAuth21Env()</code> gives a mock Authorization Server + Resource Server pair — PKCE S256 code_verifier / code_challenge (RFC 7636 mandatory in RFC 9700), DPoP proof JWT header + payload verify (RFC 9449 sender-constrained token, <code>htu</code> / <code>htm</code> / <code>jti</code> / <code>iat</code> binding), refresh token rotation with reuse detection, revocation endpoint (RFC 7009). <code>createOIDCEnv()</code> provides discovery (<code>/.well-known/openid-configuration</code>) endpoint + JWKS endpoint + JWKS rotation (<code>kid</code> header + <code>jose</code> verify wrapper) + Dynamic Client Registration (RFC 7591) + Federation trust chain (OIDC Federation 1.0 draft — trust anchor + intermediate + statement chain verify). <strong>134 new behavior tests</strong> across <code>setup-webauthn-env.test.ts</code> (21) + <code>setup-passkey-env.test.ts</code> (33) + <code>setup-oauth21-env.test.ts</code> (45) + <code>setup-oidc-env.test.ts</code> (35). Pure TypeScript — no browser, no Docker, no real Keycloak / Auth0 tenant needed at test time. Total auth package test count: 403.</li><li><strong><code>examples/dogfood-webauthn-passkey-app</code></strong> — Next.js 15 App Router + WebAuthn L3 + Passkey e2e. Ships <code>/register</code> (credential creation with attestation) + <code>/signin</code> (credential assertion) + <code>/manage</code> (credential list + delete + <code>residentKey=required</code>) routes, drives Chrome Virtual Authenticator via <code>page.context()</code> <code>addVirtualAuthenticator</code> in the real-mode Playwright suite, and drives <code>@kiwa-lab/auth</code> <code>createWebAuthnEnv</code> + <code>createPasskeyEnv</code> in the mock-mode Vitest suite. <code>WebAuthnFidelityReport</code> compares mock vs real behavior across 4 patterns (userVerification = required / preferred / discouraged / impossible-simulate, residentKey = discouraged / preferred / required, authenticatorAttachment = platform / cross-platform, and sync-fabric transitions on the same credential ID). 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-oauth21-provider</code></strong> — Hono + Cloudflare Workers custom Authorization Server. Ships 5 endpoints (<code>/authorize</code> + <code>/token</code> + <code>/revoke</code> + <code>/userinfo</code> + <code>/.well-known/oauth-authorization-server</code>) covering PKCE S256, DPoP proof binding, refresh token rotation with reuse detection, and the RFC 7009 revocation cascade. Real-mode driver hits <code>oauth2-mock-server</code>; mock-mode driver hits <code>@kiwa-lab/auth</code> <code>createOAuth21Env</code>. <code>OAuth21FidelityReport</code> compares mock vs real behavior across 4 patterns (PKCE S256 code_verifier verify — reject <code>plain</code> / mismatched verifier / DPoP proof <code>htu</code> + <code>htm</code> + <code>jti</code> uniqueness + <code>iat</code> skew — reject clock-skew &gt; 60s / refresh token rotation reuse-detection + refresh chain revoke / revocation endpoint cascade to derived access + refresh tokens). 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-oidc-federation</code></strong> — Nuxt 3 Relying Party + Deno custom OpenID Provider. Ships <code>.well-known/openid-configuration</code> Discovery, RFC 7591 Dynamic Client Registration (with <code>none</code> / <code>client_secret_basic</code> / <code>client_secret_post</code> / <code>private_key_jwt</code> auth methods + software_statement JWS), JWKS endpoint with rotation, id_token verify (iss / aud / exp / iat / nonce / at_hash / c_hash / RS256 + ES256), and Federation trust chain (trust anchor + intermediate + statement chain verify). Real-mode driver hits a mock Keycloak-shaped OP; mock-mode driver hits <code>@kiwa-lab/auth</code> <code>createOIDCEnv</code>. <code>OIDCFidelityReport</code> compares mock vs real behavior across 4 patterns (Discovery metadata field parity / DCR software_statement JWS verify + 3 auth-method issuance / JWKS rotation with <code>kid</code> rollover — old token still verifies during grace, new token verifies against new key / id_token full-claim verify — reject bad iss / aud / exp / nonce mismatch / at_hash / c_hash / Federation trust chain — 3-hop statement chain verify with intermediate substitution attack). 7-axis release gate verdict PASS.</li><li><strong>docs</strong> — 3 new tutorials (34 WebAuthn + Passkey with Virtual Authenticator + userVerification + residentKey / 35 OAuth 2.1 Authorization Server with PKCE + DPoP + refresh rotation + revocation / 36 OIDC + Federation with Discovery + DCR + JWKS rotation + id_token verify + trust chain) + additive migration guide v1.20 → v1.21 + concept doc <code>auth-protocol-testing.md</code> documenting the <strong>four protocol × four testing hard-parts</strong> (virtual authenticator / PKCE + DPoP / id_token verify / discovery + federation) as the SSOT. VitePress sidebar refreshed with a new <code>Auth 深化 (v1.21)</code> tutorial section; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#842-#847)</li><li><strong>6 PRs merged</strong> (v1.21-1 + v1.21-2/3/4/5 + this publish PR)</li><li><strong>1 new npm package minor bump</strong> (<code>@kiwa-lab/auth</code> v0.3.0 → v0.4.0) — kiwa runtime fixture count stays 34 (auth adapter is a minor extension of an existing package)</li><li><strong>3 new dogfood apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>134 new tests</strong> across the 4 protocol adapters all pass (21 WebAuthn + 33 Passkey + 45 OAuth 2.1 + 35 OIDC); 403 tests total across <code>@kiwa-lab/auth</code></li></ul><h2 id="_11-milestone-streak" tabindex="-1">11-milestone streak <a class="header-anchor" href="#_11-milestone-streak" aria-label="Permalink to &quot;11-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → v1.18 (Blockchain depth) → v1.19 (Framework 深化) → v1.20 (Streaming 深化) → <strong>v1.21 (Auth 深化)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li><li>IoT depth (MQTT / CoAP / LWM2M)</li><li>DB depth (SurrealDB / EdgeDB / Turso)</li></ul><p>Feedback welcome on which of these should land next.</p>',11)])])}const v=t(r,[["render",n]]);export{p as __pageData,v as default};
